public class X86Analyzer : ConstantPropagationAnalyzer {

	private static string PROCESSOR_NAME = "x86";

	public X86Analyzer() : base(PROCESSOR_NAME)
    {
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return program.getLanguage().getProcessor().equals(
			Processor.findOrPossiblyCreateProcessor(PROCESSOR_NAME));
	}

	/* @Override */
	public AddressSetView flowConstants(Program program, Address flowStart, AddressSetView flowSet, SymbolicPropogator symEval, TaskMonitor monitor)
    {
		
		// follow all flows building up context
		// use context to fill out addresses on certain instructions 
		ConstantPropagationContextEvaluator eval = new _Anon_ConstantPropagationContextEvaluator_1(monitor, trustWriteMemOption);
	
		eval.setTrustWritableMemory(trustWriteMemOption)
		    .setMinSpeculativeOffset(minSpeculativeRefAddress)
		    .setMaxSpeculativeOffset(maxSpeculativeRefAddress)
		    .setMinStoreLoadOffset(minStoreLoadRefAddress)
		    .setCreateComplexDataFromPointers(createComplexDataFromPointers);
		
		AddressSet resultSet = symEval.flowConstants(flowStart, flowSet, eval, true, monitor);

		return resultSet;
	}

	internal class _Anon_ConstantPropagationContextEvaluator_1 : ConstantPropagationContextEvaluator
	{
		public _Anon_ConstantPropagationContextEvaluator_1() : @base(monitor, trustWriteMemOption) {}

			
			/* @Override */
			public bool evaluateContext(VarnodeContext context, Instruction instr) {
				string mnemonic = instr.getMnemonicString();
				if (mnemonic.equals("LEA")) {
					Register reg = instr.getRegister(0);
					if (reg != null) {
						BigInteger val = context.getValue(reg, false);
						if (val != null) {
							long lval = val.longValue();
							Address refAddr = instr.getMinAddress().getNewAddress(lval);
							if ((lval > 4096 || lval < 0) && program.getMemory().contains(refAddr)) {
